@import url("https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap");
:root{--ink:#16181D;--ink-2:#2A2E37;--code:#0F1115;--vio:#6D4AFF;--vio-d:#5534E6;--vio-l:#EEEAFF;--grn:#1FB57A;--text:#22252D;--muted:#5F6573;--line:#E4E6EB;--bg:#F7F8FA;
--sans:"IBM Plex Sans",system-ui,-apple-system,"Segoe UI",sans-serif;--mono:"IBM Plex Mono",ui-monospace,monospace;--wrap:1200px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);font-size:18px;line-height:1.6;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-weight:700;margin:0;line-height:1.08;color:var(--ink);letter-spacing:-.025em}h3{font-weight:600;letter-spacing:-.01em}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--vio);color:#fff;padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--vio);outline-offset:3px;border-radius:4px}
.site-header{position:sticky;top:0;z-index:40;background:rgba(255,255,255,.95);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;height:66px}
.logo{display:flex;align-items:center;gap:10px;font-weight:700;font-size:21px;text-decoration:none;color:var(--ink)}
.logo i{width:26px;height:26px;border-radius:7px;background:var(--vio);position:relative}.logo i::after{content:"";position:absolute;inset:8px 6px;border:2px solid #fff;border-top-width:3px}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:500;color:var(--muted)}.menu a:hover{color:var(--ink)}
.nav-r{display:flex;gap:10px;align-items:center}.nav-r a.l{text-decoration:none;color:var(--muted);font-weight:500}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 20px;border-radius:8px;font-weight:600;text-decoration:none;border:1px solid transparent;font-family:var(--sans);font-size:16px;cursor:pointer}
.btn-vio{background:var(--vio);color:#fff}.btn-vio:hover{background:var(--vio-d)}
.btn-out{border-color:var(--line);color:var(--ink);background:#fff}.btn-out:hover{border-color:var(--ink)}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:8px;padding:8px 10px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:var(--ink);margin:4px 0}
.hero{padding:76px 0 90px;background-image:radial-gradient(var(--line) 1px,transparent 1px);background-size:22px 22px}
.hero-grid{display:grid;grid-template-columns:1fr 1.05fr;gap:50px;align-items:center}
.badge{display:inline-flex;gap:8px;align-items:center;font-family:var(--mono);font-size:14px;background:#fff;border:1px solid var(--line);border-radius:6px;padding:5px 12px;margin-bottom:22px}
.badge i{width:8px;height:8px;border-radius:50%;background:var(--grn)}
.hero h1{font-size:clamp(40px,5.4vw,70px)}
.hero h1 span{color:var(--vio)}
.hero .lead{font-size:20px;color:var(--muted);max-width:44ch;margin:22px 0 28px}
.actions{display:flex;gap:12px;flex-wrap:wrap}
.install{margin-top:22px;display:inline-flex;align-items:center;gap:12px;font-family:var(--mono);font-size:15px;background:var(--ink);color:#e7e9ee;border-radius:8px;padding:10px 14px}
.install button{background:var(--ink-2);color:#fff;border:0;border-radius:6px;padding:4px 10px;font:inherit;font-size:13px;cursor:pointer}
.term{background:var(--code);border-radius:14px;overflow:hidden;box-shadow:0 30px 60px -30px rgba(22,24,29,.6)}
.tabs{display:flex;gap:2px;background:#191C22;padding:8px 8px 0}
.tabs button{background:none;border:0;color:#8B93A5;font:500 14px var(--mono);padding:10px 16px;border-radius:8px 8px 0 0;cursor:pointer}
.tabs button[aria-selected="true"]{background:var(--code);color:#fff}
.panel{display:none;margin:0;padding:22px 24px;font:14px/1.75 var(--mono);color:#D5D9E2;overflow-x:auto;white-space:pre}
.panel.on{display:block}
.k{color:#C4A7FF}.s{color:#8FE3B8}.c{color:#6B7385}.f{color:#7CC4FF}
.res{border-top:1px solid #23272F;padding:14px 24px;font:13px var(--mono);color:#8FE3B8}
.logos{border-block:1px solid var(--line);padding:26px 0}
.logos .wrap{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:24px}
.logos p{margin:0;color:var(--muted);font-size:15px}.logos .row{display:flex;gap:40px;flex-wrap:wrap}.logos span{font-weight:700;font-size:19px;color:#A3A8B4}
section{padding:100px 0}
.head{max-width:740px;margin-bottom:50px}.head h2{font-size:clamp(34px,4.2vw,54px)}.head p{color:var(--muted);font-size:19px;margin-top:14px}
.kick{font-family:var(--mono);color:var(--vio);font-size:14px;display:block;margin-bottom:12px}
.feats{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.feat{padding:30px;border-right:1px solid var(--line);border-bottom:1px solid var(--line)}
.feat:nth-child(3n){border-right:0}.feat:nth-last-child(-n+3){border-bottom:0}
.feat h3{font-size:20px;margin-bottom:8px}.feat p{margin:0;color:var(--muted);font-size:16px}
.feat code{font-family:var(--mono);font-size:14px;background:var(--vio-l);color:var(--vio-d);padding:2px 6px;border-radius:4px}
.metrics{background:var(--ink);color:#B5BAC6}
.metrics h2{color:#fff}.metrics .head p{color:#9098A8}.metrics .kick{color:#C4A7FF}
.mgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.m{background:var(--ink-2);border-radius:12px;padding:24px}
.m b{font-family:var(--mono);font-size:38px;color:#fff;display:block;font-weight:500}.m span{font-size:15px}
.bars{display:flex;gap:3px;height:34px;align-items:flex-end;margin-top:30px}
.bars i{flex:1;background:var(--grn);border-radius:2px;opacity:.85}
.bars-l{display:flex;justify-content:space-between;font:13px var(--mono);margin-top:8px}
.sdk{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:center}
.chips{display:flex;flex-wrap:wrap;gap:10px}
.chips span{font-family:var(--mono);font-size:15px;border:1px solid var(--line);border-radius:8px;padding:10px 16px;background:#fff}
.sdk img{border-radius:14px;width:100%;aspect-ratio:4/3;object-fit:cover}
.pricing{background:var(--bg)}
.plans{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.plan{background:#fff;border:1px solid var(--line);border-radius:14px;padding:30px;display:flex;flex-direction:column}
.plan.hot{border:2px solid var(--vio)}
.plan h3{font-size:20px}.plan .amt{font-size:44px;font-weight:700;color:var(--ink);margin:12px 0 0;letter-spacing:-.03em}
.plan .amt small{font-size:15px;font-weight:500;color:var(--muted)}
.plan .inc{font-family:var(--mono);font-size:14px;color:var(--vio-d);margin:4px 0 0}
.plan ul{list-style:none;padding:0;margin:18px 0 24px;font-size:16px}.plan li{padding:7px 0 7px 24px;position:relative}
.plan li::before{content:"→";position:absolute;left:0;color:var(--vio)}
.plan .btn{margin-top:auto}
.over{margin-top:18px;font-size:15px;color:var(--muted)}
.quote{display:grid;grid-template-columns:auto 1fr;gap:30px;align-items:center;border:1px solid var(--line);border-radius:16px;padding:36px}
.quote img{width:96px;height:96px;border-radius:50%;object-fit:cover}
.quote p{font-size:22px;color:var(--ink);font-weight:500;margin-bottom:10px}.quote span{color:var(--muted);font-size:16px}
.faq{max-width:820px}
.faq details{border-bottom:1px solid var(--line);padding:18px 0}
.faq summary{list-style:none;cursor:pointer;font-weight:600;font-size:19px;display:flex;justify-content:space-between;gap:18px;color:var(--ink)}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";font-family:var(--mono);font-size:22px;color:var(--vio)}
.faq details[open] summary::after{content:"-"}.faq details p{margin:10px 0 0;color:var(--muted)}
.cta{background:var(--vio);color:#E7E1FF}
.cta .wrap{display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap}
.cta h2{color:#fff;font-size:clamp(32px,4vw,50px);max-width:18ch}.cta p{margin:12px 0 0;font-size:19px}
.cta .btn-out{border-color:#fff}
footer{background:var(--ink);color:#9098A8;padding:50px 0 28px;font-size:15px}
.foot{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:30px;margin-bottom:30px}
footer .logo{color:#fff}footer h3{color:#fff;font-size:15px;margin-bottom:12px}
footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:8px}footer a{text-decoration:none}footer a:hover{color:#fff}
.status{display:inline-flex;gap:8px;align-items:center;margin-top:14px;font-family:var(--mono);font-size:14px;color:#8FE3B8}.status i{width:8px;height:8px;border-radius:50%;background:var(--grn)}
.legal{border-top:1px solid var(--ink-2);padding-top:18px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
@media (max-width:1000px){.menu,.nav-r{display:none}.burger{display:block}
.menu.open{display:flex;flex-direction:column;position:absolute;top:66px;left:0;right:0;background:#fff;padding:22px;border-bottom:1px solid var(--line);gap:16px}
.hero-grid,.sdk{grid-template-columns:1fr}.feats{grid-template-columns:1fr 1fr}.feat{border-right:1px solid var(--line)!important;border-bottom:1px solid var(--line)!important}
.mgrid{grid-template-columns:1fr 1fr}.plans{grid-template-columns:1fr}.foot{grid-template-columns:1fr 1fr}}
@media (max-width:600px){body{font-size:17px}section{padding:72px 0}.feats,.mgrid{grid-template-columns:1fr}.feat{border-right:0!important}.quote{grid-template-columns:1fr}.panel{font-size:12px}}

