const tabs=[...document.querySelectorAll('[role=tab]')];
tabs.forEach(t=>t.addEventListener('click',()=>{tabs.forEach(x=>{x.setAttribute('aria-selected',x===t);document.getElementById(x.getAttribute('aria-controls')).classList.toggle('on',x===t)})}));
document.getElementById('copy').addEventListener('click',e=>{navigator.clipboard&&navigator.clipboard.writeText(document.getElementById('cmd').textContent);e.target.textContent='Copied'});
const bars=document.getElementById('bars');for(let i=0;i<90;i++){const h=78+Math.round(Math.abs(Math.sin(i*1.7))*22);bars.insertAdjacentHTML('beforeend',`<i style="height:${h}%"></i>`)}
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
